<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { SourceSummary } from '../types'
const props = defineProps<{ summary: SourceSummary }>()
const metric = ref<'count' | 'answers'>('answers')
const model = ref(''), category = ref(''), kind = ref(''), mentioned = ref(''), anomaly = ref(''), query = ref(''), module = ref(''), answerMode = ref(''), brandFilter = ref('')
const authority = ref(''), ownership = ref(''), authorityPreset = ref('')
const page = ref(1), size = ref(50), notice = ref('')
const selectedCategory = ref('')
const TRUSTED = ['certification_body','distributor','directory','trade_media']
const rows = computed(() => (props.summary.allItems || []).filter(x => (!model.value || x.modelId === model.value) && (!category.value || x.category === category.value) && (!module.value || x.module === module.value) && (!answerMode.value || x.answerMode === answerMode.value) && (!brandFilter.value || (brandFilter.value === 'degson' ? x.brands?.some(b=>b.brandId==='degson') : x.brands?.some(b=>b.brandId!=='degson'))) && (!kind.value || x.kind === kind.value) && (!authority.value || x.authority === authority.value) && (!ownership.value || x.ownership === ownership.value) && (authorityPreset.value !== 'low' || x.authority === 'blog_or_reseller') && (authorityPreset.value !== 'trusted' || TRUSTED.includes(x.authority || '')) && (!mentioned.value || !!x.mentioned === (mentioned.value === 'yes')) && (!anomaly.value || (anomaly.value === 'normal' ? !['test','redirect'].includes(x.kind) : x.kind === anomaly.value)) && (!query.value || [x.host,x.title,x.url].join(' ').toLowerCase().includes(query.value.toLowerCase()))))
const pages = computed(() => Math.max(1, Math.ceil(rows.value.length / size.value)))
const visible = computed(() => rows.value.slice((page.value-1)*size.value,page.value*size.value))
watch([model,category,module,answerMode,brandFilter,kind,authority,ownership,authorityPreset,mentioned,anomaly,query,size,() => props.summary], () => { page.value=1 })
const categoryData = computed(() => props.summary.byCategory.find(x => x.category === selectedCategory.value) || props.summary.byCategory[0])
function ranked<T extends { count: number; answers?: number }>(rows: T[]) { return [...rows].sort((a,b) => metric.value === 'count' ? b.count-a.count || (b.answers||0)-(a.answers||0) : (b.answers||0)-(a.answers||0) || b.count-a.count) }
const groups = computed(() => [{title:'整体来源',rows:ranked(props.summary.allCategories)},{title:'DEGSON 相关来源',rows:props.summary.degson.mentioned ? ranked(props.summary.degson.categories) : []},{title:'DEGSON 缺席来源',rows:ranked(props.summary.absent.categories)}])
const hostKind = ref('')
const monitoredHosts = computed(() => ranked(props.summary.hostStats || []).filter(x=>!hostKind.value || (hostKind.value==='degson' ? props.summary.allItems.some(y=>y.host===x.host && y.degsonRelated) : x.kind===hostKind.value)))
function downloadHosts() { const values=[['站点','类型','引用条数','回答数','问题数','模型'],...monitoredHosts.value.map(x=>[x.host,x.kindLabel,x.citations,x.answers,x.questions,x.models.join(' / ')])]; const blob=new Blob(['\ufeff'+values.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='source-hosts.csv';a.click();URL.revokeObjectURL(url) }
const thirdParty = ['distributor','certification','media','directory','research','local','marketplace']
function share(m: SourceSummary['models'][number], ids: string[]) { return m.citations ? ((m.categories || []).filter(x => ids.includes(x.id)).reduce((n,x)=>n+x.count,0)/m.citations*100).toFixed(1)+'%' : '—' }
const csv = computed(() => { const values=[['问题','模型','品类','提到DEGSON','类型','权威性','归属','标题','URL','原始URL','来源通道'],...rows.value.map(x=>[x.questionId,x.modelId,x.category,x.mentioned?'是':'否',x.kindLabel,x.authorityLabel||'',x.ownership||'',x.title,x.url,(x.rawUrls || [x.rawUrl || x.url]).join(' | '),(x.origins || [x.origin || '']).join(' | ')])]; return values.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n') })
function authClass(id?: string) { return id === 'blog_or_reseller' ? 'auth-low' : id === 'unknown' ? 'auth-unknown' : id === 'manufacturer' ? 'auth-maker' : '' }
const lowShare = computed(() => props.summary.withCitations ? (props.summary.authoritySummary?.lowAuthority.answers || 0) / props.summary.withCitations : 0)
function download() { const url=URL.createObjectURL(new Blob(['\ufeff'+csv.value],{type:'text/csv;charset=utf-8'})); const a=document.createElement('a');a.href=url;a.download='source-analysis-filtered.csv';a.click();URL.revokeObjectURL(url) }
async function copy() { try { await navigator.clipboard.writeText(csv.value);notice.value='已复制当前筛选的全部结果' } catch { notice.value='浏览器不允许复制，请使用导出 CSV' } }
const originLabel = (x:string) => ({text:'正文链接',citation:'引用标注',retrieval:'检索来源'}[x] || x)
</script>

<template>
<section class="sources" aria-label="引用来源统计">
<h3>引用来源统计</h3>
<h4>按模块</h4><p>模块加权分 {{ summary.moduleScore ?? '—' }}%（仅用于内部优先级）</p>
<div class="filters" role="tablist"><button role="tab" :aria-selected="!module" @click="module=''">全部</button><button v-for="name in Object.keys(summary.byModule || {})" :key="name" role="tab" :aria-selected="module===name" @click="module=name">{{ name }}</button></div>
<table><thead><tr><th>模块</th><th>题数</th><th>品牌回答</th><th>DEGSON 提及</th><th>提及率</th><th>有来源</th><th>目标页命中</th></tr></thead><tbody><tr v-for="(stat,name) in summary.byModule || {}" :key="name"><td>{{ name }}</td><td>{{ stat.questionCount }}</td><td>{{ stat.brandAnswerCount }}</td><td>{{ stat.degsonMentions }}</td><td>{{ stat.degsonRate ?? '—' }}%</td><td>{{ stat.sourceAnswers }}</td><td>{{ stat.targetHits }}</td></tr></tbody></table>
<h4>按回答模式</h4><table><thead><tr><th>模式</th><th>题数</th><th>回答</th><th>提到 DEGSON</th><th>有来源</th><th>目标页命中</th></tr></thead><tbody><tr v-for="(stat,name) in summary.byAnswerMode || {}" :key="name"><td>{{ name }}</td><td>{{ stat.questionCount }}</td><td>{{ stat.answerCount }}</td><td>{{ stat.degsonMentions }}</td><td>{{ stat.sourceAnswers }}</td><td>{{ stat.targetHits }}</td></tr></tbody></table>
<h4>品牌来源</h4><table><thead><tr><th>品牌</th><th>Host</th><th>引用</th><th>回答</th><th>问题</th><th>模型</th></tr></thead><tbody><tr v-for="x in summary.sourceBrands || []" :key="x.brandId"><td>{{ x.brandName }}</td><td>{{ x.hosts.join('、') }}</td><td>{{ x.citations }}</td><td>{{ x.answers }}</td><td>{{ x.questions }}</td><td>{{ x.models.join(' / ') }}</td></tr></tbody></table>
<h4>竞品来源地图</h4><table><thead><tr><th>品牌</th><th>Host</th><th>类型</th><th>引用</th><th>回答</th><th>问题</th><th>模型</th></tr></thead><tbody><tr v-for="(x,i) in summary.competitorSourceMap || []" :key="i"><td>{{ x.brandName }}</td><td>{{ x.host }}</td><td>{{ x.kindLabel }}</td><td>{{ x.citations }}</td><td>{{ x.answers }}</td><td>{{ x.questions }}</td><td>{{ x.models.join(' / ') }}</td></tr></tbody></table>
<p>同一回答内同一规范化 URL 只计一次；跨回答分别计次。检索来源与回答引用分别保留通道标记，域名类型不代表权威性。</p>
<div class="kpis">
<div>有来源回答<strong>{{ summary.withCitations }} / {{ summary.answers }}</strong></div>
<div>唯一来源<strong>{{ summary.uniqueUrlCount ?? '—' }}</strong><small>总引用 {{ summary.allCitationCount }} 条 · {{ summary.uniqueHostCount }} 个域名</small></div>
<div>第三方占比<strong>{{ summary.thirdPartyShare ?? 0 }}%</strong></div>
<div>竞品占比<strong>{{ summary.competitorShare ?? 0 }}%</strong></div>
<div>DEGSON 有引用<strong>{{ summary.degson.sourced }} / {{ summary.degson.mentioned }}</strong></div>
<div>权威第三方<strong>{{ summary.authoritySummary ? `${summary.authoritySummary.authoritativeThirdParty.answers} / ${summary.withCitations}` : '—' }}</strong><small>认证库、经销商、目录、行业媒体</small></div>
<div>厂商自述<strong>{{ summary.authoritySummary?.manufacturerClaims.answers ?? '—' }}</strong><small>含 DEGSON 与竞品官网</small></div>
<div>低权威<strong>{{ summary.authoritySummary ? `${summary.authoritySummary.lowAuthority.answers} / ${summary.withCitations}` : '—' }}</strong></div>
<div>异常<strong>{{ summary.testCount || summary.redirectCount ? `测试站 ${summary.testCount || 0} · 未解析 ${summary.redirectCount || 0}` : '无异常' }}</strong></div>
</div>
<p v-if="summary.authoritySummary && lowShare > 0.2" class="warn" role="status">本轮低权威来源占比较高，不要把“被引用”当成“被验证”。</p>
<h4>来源权威性</h4>
<p v-if="!summary.byAuthority?.length">暂无权威性数据</p>
<table v-else><thead><tr><th>权威类型</th><th>引用条数</th><th>回答数</th><th>覆盖率</th><th>唯一域名</th><th>第一方</th><th>第三方</th></tr></thead><tbody><tr v-for="x in summary.byAuthority" :key="x.id" :class="authClass(x.id)"><td>{{ x.label }}</td><td>{{ x.citations }}</td><td>{{ x.answers }}</td><td>{{ x.answerPercent }}%</td><td>{{ x.uniqueHosts }}</td><td>{{ x.firstPartyCitations }}</td><td>{{ x.thirdPartyCitations }}</td></tr></tbody></table>
<p v-if="summary.authoritySummary?.lowAuthority.topHosts?.length">低权威域名：{{ summary.authoritySummary.lowAuthority.topHosts.map(x => `${x.host}（${x.count}条 / ${x.answers}回答）`).join('、') }}</p>
<p v-if="summary.coverage">有来源回答 {{ summary.withCitations }} / {{ summary.answers }} · 竞品覆盖 {{ summary.coverage.competitor.answers }}/{{ summary.withCitations }}（{{ summary.coverage.competitor.percent }}%）· 目录覆盖 {{ summary.coverage.directory.answers }}/{{ summary.withCitations }}（{{ summary.coverage.directory.percent }}%）· 官网覆盖 {{ summary.coverage.official.answers }}/{{ summary.withCitations }}（{{ summary.coverage.official.percent }}%）</p>
<p>DEGSON 缺席（有品牌回答）：{{ summary.absent.brandAnswers ?? 0 }}；无品牌回答（不计入品牌分母）：{{ summary.absent.noBrandAnswers ?? 0 }}。</p>
<p v-if="summary.testCount" role="status">测试站 {{ summary.testCount }} 条：{{ [...new Set(summary.allItems.filter(x=>x.kind==='test').map(x=>x.host))].join('、') }}，不归为官网。</p>
<p v-if="summary.redirectCount" role="status">未解析引用 {{ summary.redirectCount }} 条：grounding 等跳转链接，不归为媒体或目录。</p>
<p v-if="summary.allCategories.some(x=>x.id==='other')">其他网页：{{ summary.allCategories.find(x=>x.id==='other')?.count }} 条；待分类域名：{{ [...new Set(summary.allItems.filter(x=>x.kind==='other').map(x=>x.host))].slice(0,8).join('、') }}。</p>
<p v-if="!summary.allCitationCount">本轮没有留下可核验来源</p>
<template v-else>
<label>统计口径 <select v-model="metric"><option value="answers">按回答覆盖</option><option value="count">按引用条数</option></select></label>
<p>{{ metric==='count' ? '占比以各组来源条数为分母。' : '覆盖率以各组有来源回答数为分母；同一回答可覆盖多个类型，合计可超过100%。' }} 测试站、未解析单列，仍保留在总来源分母中。</p>
<div class="structures"><section v-for="group in groups" :key="group.title"><h4>{{ group.title }}</h4><p v-if="group.title==='DEGSON 相关来源' && !summary.degson.mentioned">本轮未提到 DEGSON</p><table v-else><thead><tr><th>类型</th><th>{{ metric==='count'?'引用条数':'回答数' }}</th><th>{{ metric==='answers'?'覆盖率':'占比' }}</th><th>域名</th></tr></thead><tbody><tr v-for="x in group.rows" :key="x.id"><td>{{ x.label }}</td><td>{{ metric==='count'?x.count:x.answers }}</td><td>{{ metric==='count'?x.percent:x.answerPercent }}%</td><td>{{ x.uniqueHosts }}</td></tr></tbody></table></section></div>
<h4>模型 × 来源类型</h4><div class="scroll"><table><thead><tr><th>来源类型</th><template v-for="m in summary.models" :key="m.modelId"><th>{{ m.modelId }} 条数</th><th>{{ m.modelId }} 回答数</th></template></tr></thead><tbody><tr v-for="x in ranked(summary.allCategories)" :key="x.id"><td>{{ x.label }}</td><template v-for="m in summary.models" :key="m.modelId"><td>{{ m.categories?.find(y=>y.id===x.id)?.count || 0 }}</td><td>{{ m.categories?.find(y=>y.id===x.id)?.answers || 0 }}</td></template></tr><tr><td>官网占比</td><td v-for="m in summary.models" :key="m.modelId" colspan="2">{{ share(m,['official']) }}</td></tr><tr><td>第三方占比</td><td v-for="m in summary.models" :key="m.modelId" colspan="2">{{ share(m,thirdParty) }}</td></tr></tbody></table></div>
<p v-for="m in summary.models" :key="m.modelId">{{ m.modelId }}：<strong v-if="m.coverage?.official.answers===0" style="color:var(--danger,#b42318)">官网缺口（本轮无官网引用）</strong><span v-if="m.coverage && m.coverage.directory.answers>0" style="color:var(--success,#147d45)"> 目录有效（本轮有目录引用）</span></p>
<h4>模型 × 权威性</h4>
<p v-if="!summary.byAuthority?.length">暂无权威性数据</p>
<div v-else class="scroll"><table><thead><tr><th>权威类型</th><template v-for="m in summary.models" :key="m.modelId"><th>{{ m.modelId }} 条数</th><th>{{ m.modelId }} 回答</th></template></tr></thead><tbody><tr v-for="x in summary.byAuthority" :key="x.id" :class="authClass(x.id)"><td>{{ x.label }}</td><template v-for="m in summary.models" :key="m.modelId"><td>{{ m.byAuthority?.find(y=>y.id===x.id)?.citations || 0 }}</td><td>{{ m.byAuthority?.find(y=>y.id===x.id)?.answers || 0 }}</td></template></tr></tbody></table></div>
<h4>目标页命中</h4><p v-if="!summary.targetLanding?.length">未配置目标页</p><table v-else><thead><tr><th>目标页</th><th>模块</th><th>类型</th><th>配置问题数</th><th>命中回答</th><th>命中引用</th><th>模型</th><th>未命中问题</th></tr></thead><tbody><tr v-for="x in summary.targetLanding" :key="x.id"><td>{{ x.label }}<p v-if="!x.answers">本轮没有记录到目标引用，不能据此判断模型是否打开或检索过该页。</p><a v-for="url in x.hitUrls" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{ url }}</a></td><td>{{ x.module }}</td><td>{{ x.type }}</td><td>{{ x.questions.length || '全轮' }}</td><td>{{ x.answers }}</td><td>{{ x.citations }}</td><td>{{ x.models.join(' / ') }}</td><td>{{ x.missingQuestions.join('、') }}</td></tr></tbody></table>
<h4>Host 监控（最多100站点）</h4><select v-model="hostKind" aria-label="站点类型"><option value="">全部站点</option><option value="directory">只看目录</option><option value="media">只看媒体</option><option value="competitor">只看竞品</option><option value="degson">只看 DEGSON 相关</option></select><button @click="downloadHosts">导出站点 CSV</button><table><thead><tr><th>站点</th><th>类型</th><th>引用条数</th><th>回答数</th><th>唯一问题数</th><th>模型</th></tr></thead><tbody><tr v-for="x in monitoredHosts" :key="x.host"><td>{{ x.host }}</td><td>{{ x.kindLabel }}</td><td>{{ x.count }}</td><td>{{ x.answers }}</td><td>{{ x.questions }}</td><td>{{ x.models.join(' / ') }}</td></tr></tbody></table>
<h4>分品类来源</h4><div class="filters" role="tablist"><button v-for="x in summary.byCategory" :key="x.category" role="tab" :aria-selected="categoryData?.category===x.category" @click="selectedCategory=x.category;category=x.category">{{ x.category }}</button></div>
<section v-if="categoryData"><p>{{ categoryData.category }}：回答 {{ categoryData.answers }} · 有来源回答 {{ categoryData.withCitations }} · 引用 {{ categoryData.citationCount }} · 提到 DEGSON {{ categoryData.mentioned }} · DEGSON 有引用 {{ categoryData.sourced }}</p><p v-if="categoryData.byAuthority?.length">权威性：{{ categoryData.byAuthority.filter(x=>x.citations).map(x=>`${x.label} ${x.citations}条/${x.answers}回答`).join('、') }}</p><table><thead><tr><th>来源类型</th><th>条数</th><th>回答数</th></tr></thead><tbody><tr v-for="x in ranked(categoryData.categories)" :key="x.id"><td>{{ x.label }}</td><td>{{ x.count }}</td><td>{{ x.answers }}</td></tr></tbody></table><p>Top 站点：{{ ranked(categoryData.topHosts).map(x=>`${x.host}（${x.count}条 / ${x.answers}回答）`).join('、') }}</p><details><summary>该品类目标页面（高松相关）</summary><ul><li v-for="url in [...new Set(categoryData.items.filter(x=>x.degsonRelated).map(x=>x.url))]" :key="url"><a :href="url" target="_blank" rel="noopener noreferrer">{{ url }}</a></li></ul><p>仅列本轮高松相关 URL，不推断预设目标页命中。</p></details><button @click="category=categoryData.category">查看该品类逐条来源</button></section>
<h4>逐条来源</h4><div class="filters"><select v-model="answerMode" aria-label="回答模式"><option value="">全部回答模式</option><option v-for="name in Object.keys(summary.byAnswerMode || {})" :key="name" :value="name">{{ name }}</option></select><select v-model="brandFilter" aria-label="品牌来源"><option value="">全部品牌来源</option><option value="degson">只看 DEGSON</option><option value="competitor">只看竞品</option></select><select v-model="model" aria-label="模型"><option value="">全部模型</option><option v-for="x in summary.models" :key="x.modelId">{{ x.modelId }}</option></select><select v-model="category" aria-label="品类"><option value="">全部品类</option><option v-for="x in summary.byCategory" :key="x.category">{{ x.category }}</option></select><select v-model="mentioned" aria-label="是否提到DEGSON"><option value="">全部回答</option><option value="yes">提到 DEGSON</option><option value="no">未提到 DEGSON</option></select><select v-model="kind" aria-label="来源类型"><option value="">全部类型</option><option v-for="x in ranked(summary.allCategories)" :key="x.id" :value="x.id">{{ x.label }}</option></select><select v-model="authority" aria-label="权威性"><option value="">全部权威性</option><option v-for="x in summary.byAuthority || []" :key="x.id" :value="x.id">{{ x.label }}</option></select><select v-model="ownership" aria-label="归属"><option value="">全部归属</option><option value="first_party">第一方</option><option value="third_party">第三方</option><option value="unknown">未判断</option></select><select v-model="authorityPreset" aria-label="权威快捷筛选"><option value="">不限权威层</option><option value="low">只看低权威</option><option value="trusted">只看认证库/经销商/目录/媒体</option></select><select v-model="anomaly" aria-label="异常"><option value="">全部状态</option><option value="normal">普通来源</option><option value="test">测试站</option><option value="redirect">未解析</option></select><input v-model="query" placeholder="搜索域名、标题或 URL" aria-label="搜索来源"/><button @click="download">导出 CSV</button><button @click="copy">复制筛选结果</button></div><p role="status">{{ notice }}</p>
<div class="scroll"><table><thead><tr><th>问题</th><th>模型 / 品类</th><th>DEGSON</th><th>类型 / 通道</th><th>页面与原始 URL</th></tr></thead><tbody><tr v-for="(x,i) in visible" :key="i"><td>{{ x.questionId }}</td><td>{{ x.modelId }} / {{ x.category }}</td><td>{{ x.mentioned?'提到':'未提到' }}</td><td><span class="badge">{{ x.kindLabel }}</span><span v-if="x.authorityLabel" class="badge" :class="authClass(x.authority)">{{ x.authorityLabel }}</span><span v-for="origin in x.origins || [x.origin || '']" :key="origin" class="badge">{{ originLabel(origin) }}</span></td><td><a :href="x.url" :title="x.url" target="_blank" rel="noopener noreferrer">{{ x.title || x.url }}</a><details><summary>原始 URL</summary><p v-for="url in x.rawUrls || [x.rawUrl || x.url]" :key="url">{{ url }}</p></details></td></tr></tbody></table></div>
<div class="filters"><span>共 {{ rows.length }} 条 · 第 {{ page }}/{{ pages }} 页</span><select v-model.number="size" aria-label="每页条数"><option :value="50">每页50条</option><option :value="100">每页100条</option></select><button :disabled="page<=1" @click="page--">上一页</button><button :disabled="page>=pages" @click="page++">下一页</button></div>
</template></section>
</template>
<style scoped>
.sources{font-size:13px}.sources h3{margin-top:0}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:14px 0}.kpis>div{padding:12px;border:1px solid var(--border)}strong,small{display:block}.structures{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:8px;text-align:left;border-bottom:1px solid var(--border);vertical-align:top}td{overflow-wrap:anywhere}.scroll{overflow:auto}.filters{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:12px 0}select,input,button{padding:6px;max-width:100%}.badge{display:inline-block;border:1px solid var(--border);padding:2px 5px;margin:2px}.auth-low{color:#b54708}.auth-unknown{color:#667085}.auth-maker{color:#344054}.warn{color:#b54708}details p{overflow-wrap:anywhere}a{color:var(--accent,#2563eb)}
</style>
